Algorithm AHOGS(problem_spec, time_limit, seed)
  // Adaptive Hierarchical Operator-Guided Search (task-agnostic)
  Init problem-specific hooks: ENCODE, DECODE, COST, VALIDATE, REPAIR, OPERATORS, DECOMPOSE
  operator_weights := uniform(OPERATORS); credits := zero(OPERATORS)
  population := seed_population(problem_spec, seed, heuristics + random); elite_archive := {}
  for s in population: s := REPAIR(s); s.cost := COST(s); if VALIDATE(s) add_to_archive(elite_archive,s)
  while not stop_condition(time_limit, iteration, stagnation):
    subproblems := DECOMPOSE(population, elite_archive, adaptivity)   // cluster cities/customers/jobs/blocks
    for sub in select_focus(subproblems, budget):
      parent := select_parent(population, elite_archive, fitness+diversity)
      op := choose_operator(operator_weights, context=sub)
      child := APPLY_OPERATOR(parent, op, context=sub)
      child := LOCAL_REPAIR_AND_IMPROVE(child, sub, OPERATORS.local_search)
      if not VALIDATE(child): child := REPAIR(child)
      child.cost := EVALUATE(child, COST, surrogate_option)
      delta := improvement_metric(child, parent)
      credits[op] += credit_function(delta, feasibility_gain, novelty)
      population := replacement_policy(population, child, strategy=age_diversity)
      update_archive(elite_archive, child)
    operator_weights := adapt_weights(operator_weights, credits, decay, exploration)
    if periodic_recombine(): population := recombine_elites(elite_archive, OPERATORS.recombine)
  return best(elite_archive)

